// Categories that schools typically block (simulated ❌).
const SIM_BLOCKED_CATEGORIES = new Set([
  "gambling", "adult", "pornography", "malware", "phishing",
  "violence", "weapons", "drugs", "hate", "dating",
]);

const statusEl = document.getElementById("status");
const resultsSection = document.getElementById("results-section");
const resultsList = document.getElementById("results-list");
const resultsTitle = document.getElementById("results-title");
const realBadge = document.getElementById("real-badge");
const form = document.getElementById("check-form");
const urlInput = document.getElementById("url-input");
const checkBtn = document.getElementById("check-btn");

document.getElementById("year").textContent = new Date().getFullYear();

/* ---------- helpers ---------- */

function normalizeDomain(raw) {
  let value = raw.trim();
  if (!value) throw new Error("Enter a URL or domain first.");
  if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(value)) value = "https://" + value;
  let url;
  try {
    url = new URL(value);
  } catch {
    throw new Error("That doesn't look like a valid URL.");
  }
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/i.test(url.hostname)) {
    throw new Error("That doesn't look like a valid domain.");
  }
  return url.hostname.toLowerCase().replace(/^www\./, "");
}

function setStatus(message, isError = false) {
  statusEl.textContent = message;
  statusEl.classList.toggle("error", isError);
}

/* ---------- live DNSFilter lookup ---------- */

// Replace with your own backend proxy URL for production.
// Example proxy: /api/dnsfilter-lookup?fqdn=example.com
const DNSFILTER_PROXY_URL = "";

async function lookupDNSFilter(domain) {
  // If no proxy is configured, return a clearly-marked simulated result.
  if (!DNSFILTER_PROXY_URL) {
    return {
      live: false,
      category: "Information Technology",
      note: "No DNSFilter proxy configured — showing simulated category.",
    };
  }
  const resp = await fetch(`${DNSFILTER_PROXY_URL}?fqdn=${encodeURIComponent(domain)}`);
  if (!resp.ok) throw new Error(`DNSFilter lookup failed (${resp.status})`);
  const data = await resp.json();
  return {
    live: true,
    category: data.category || "Unknown",
    blocked: typeof data.blocked === "boolean" ? data.blocked : null,
  };
}

/* ---------- rendering ---------- */

function buildRow(vendor, category, isLive) {
  const li = document.createElement("li");
  li.className = "result-row";

  const icon = document.createElement("span");
  icon.className = "vendor-icon";
  icon.textContent = vendor.icon;

  const name = document.createElement("span");
  name.className = "vendor-name";
  name.textContent = vendor.name;

  const cat = document.createElement("span");
  cat.className = "category";
  cat.textContent = `(${category})`;

  const mark = document.createElement("span");
  const blocked = SIM_BLOCKED_CATEGORIES.has(category.toLowerCase());
  mark.className = "mark " + (blocked ? "blocked" : "allowed");
  mark.textContent = blocked ? "❌" : "✅";
  mark.title = blocked ? "Simulated: blocked" : "Simulated: allowed";

  const source = document.createElement("span");
  source.className = "source badge " + (isLive ? "badge-real" : "badge-sim");
  source.textContent = isLive ? "Live" : "Sim";

  li.append(icon, name, cat, mark, source);
  return li;
}

function renderResults(domain, dnsResult) {
  resultsList.innerHTML = "";

  const genericKey = (dnsResult.category || "information technology").toLowerCase();
  const labelMap = SIM_LABELS[genericKey] || SIM_LABELS._default;

  // Live DNSFilter row first, using real category.
  const dnsVendor = VENDORS.find(v => v.key === "dnsfilter");
  if (dnsResult.live) {
    const liveCat = dnsResult.category;
    const li = document.createElement("li");
    li.className = "result-row";
    li.innerHTML = `
      <span class="vendor-icon">${dnsVendor.icon}</span>
      <span class="vendor-name">${dnsVendor.name}</span>
      <span class="category">(${escapeHtml(liveCat)})</span>
      <span class="mark ${dnsResult.blocked ? "blocked" : "allowed"}">${dnsResult.blocked ? "❌" : "✅"}</span>
      <span class="source badge badge-real">Live</span>`;
    resultsList.appendChild(li);
    realBadge.hidden = false;
  } else {
    resultsList.appendChild(buildRow(dnsVendor, labelMap.dnsfilter || "Information Technology", false));
    realBadge.hidden = true;
    if (dnsResult.note) setStatus(dnsResult.note);
  }

  // Simulated rows for every other vendor.
  VENDORS.filter(v => v.mode === "sim").forEach(v => {
    resultsList.appendChild(buildRow(v, labelMap[v.key] || "Uncategorized", false));
  });

  resultsTitle.textContent = `Results for ${domain}`;
  resultsSection.hidden = false;
  resultsSection.scrollIntoView({ behavior: "smooth", block: "start" });
}

function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, c => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  }[c]));
}

/* ---------- form handling ---------- */

form.addEventListener("submit", async (e) => {
  e.preventDefault();
  resultsSection.hidden = true;
  setStatus("");

  let domain;
  try {
    domain = normalizeDomain(urlInput.value);
  } catch (err) {
    setStatus(err.message, true);
    return;
  }

  checkBtn.disabled = true;
  setStatus(`Checking ${domain}…`);

  try {
    const dnsResult = await lookupDNSFilter(domain);
    renderResults(domain, dnsResult);
    if (dnsResult.live) setStatus("DNSFilter result loaded.");
    else setStatus(dnsResult.note || "Showing simulated results.");
  } catch (err) {
    // Fall back to simulated-only rendering if the live call fails.
    renderResults(domain, {
      live: false,
      category: "Information Technology",
      note: "Live lookup failed — showing simulated results.",
    });
    setStatus(`Live lookup failed: ${err.message}. Showing simulated results.`, true);
  } finally {
    checkBtn.disabled = false;
  }
});

